async def start_memory_oauth(provider: str, profile: Optional[str] = None):
    """Begin a provider's zero-CLI OAuth flow (browser + loopback listener); returns immediately, poll status."""
    try:
        # The flow resolves its config path eagerly inside this scope; its worker thread outlives it.
        with _scope_to_profile(profile):
            flow = _resolve_flow(provider)
            return flow.start_loopback_flow_background()
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to start {provider} OAuth: {exc}")

async def memory_oauth_status(provider: str, profile: Optional[str] = None):
    """Poll a provider's OAuth flow: idle | pending | connected | error."""
    try:
        with _scope_to_profile(profile):
            flow = _resolve_flow(provider)
            return flow.get_flow_status()
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to read {provider} OAuth status: {exc}")

async def serve_css(filename: str, request: Request):
        css_path = WEB_DIST / "assets" / f"{filename}.css"
        if not css_path.is_file() or not css_path.resolve().is_relative_to(WEB_DIST.resolve()):
            return JSONResponse({"error": "not found"}, status_code=404)
        prefix = _normalise_prefix(request.headers.get("x-forwarded-prefix"))
        css = css_path.read_text(encoding="utf-8-sig")
        if prefix:
            for asset_dir in ("/fonts/", "/fonts-terminal/", "/ds-assets/", "/assets/"):
                for quote in ("", '"', "'"):
                    css = css.replace(f"url({quote}{asset_dir}", f"url({quote}{prefix}{asset_dir}")
        return Response(
            content=css, media_type="text/css", headers={"Cache-Control": _IMMUTABLE_ASSET_CACHE_CONTROL}
        )

async def serve_spa(full_path: str, request: Request):
        prefix = _normalise_prefix(request.headers.get("x-forwarded-prefix"))
        # An unmatched /api/* path is a missing endpoint, not a client-side route: return a
        # real 404 JSON instead of index.html (which breaks JSON clients with a SyntaxError).
        if full_path == "api" or full_path.startswith("api/"):
            return JSONResponse({"detail": f"No such API endpoint: /{full_path}"}, status_code=404)
        file_path = WEB_DIST / full_path
        # Prevent path traversal via url-encoded sequences (%2e%2e/)
        if (
            full_path
            and file_path.resolve().is_relative_to(WEB_DIST.resolve())
            and file_path.exists()
            and file_path.is_file()
        ):
            return FileResponse(file_path)
        return _serve_index(prefix)

async def api_auth_providers() -> Any:
    # Only interactive providers are sign-in options; fail closed on zero.
    providers = list_session_providers()
    if not providers:
        return JSONResponse({"detail": "no auth providers registered"}, status_code=503)
    return {"providers": [
        {"name": p.name, "display_name": p.display_name,
         "supports_password": bool(getattr(p, "supports_password", False))}
        for p in providers]}

async def auth_login(request: Request, provider: str, next: str = ""):
    p = get_provider(provider)
    if p is None:
        raise _http(404, f"Unknown provider: {provider!r}")
    if not getattr(p, "supports_session", True):
        raise _http(404, f"Provider does not support interactive login: {provider!r}")
    safe_next = _validate_post_login_target(next)
    if getattr(p, "supports_password", False):
        login_url = f"{_prefix(request)}/login"
        if safe_next:
            login_url = f"{login_url}?next={quote(safe_next, safe='')}"
        return RedirectResponse(url=login_url, status_code=302)
    resp = _start_upstream_login(
        request, p, audit_failure=True, extra_pkce={"next": safe_next} if safe_next else {})
    _audit(request, AuditEvent.LOGIN_START, provider=provider)
    return resp

async def gateway_drain(request: Request):
    """Begin or cancel an external (NAS-driven) gateway drain.

    Authenticated by the non-interactive token-auth seam (the ``dashboard_auth/drain``
    plugin registers this path as a token route and verifies the bearer secret);
    without that plugin the cookie gate covers a gated bind and the legacy
    session-token gate a loopback bind — never unauthenticated on a network bind.

    Body ``{"action": "drain"|"cancel"}``. Only the ``.drain_request.json`` marker is
    written/removed here — the gateway's ``_drain_control_watcher`` owns the state
    transition (the marker IS the control channel). Idempotent on both sides;
    ``POST /api/gateway/restart`` is the force-override that supersedes a drain.
    """
    from gateway.drain_control import clear_drain_request, drain_requested, write_drain_request

    try:
        body = await request.json()
    except Exception:
        body = {}
    body = body or {}
    action = str(body.get("action", "drain")).strip().lower()
    # Attribute to the verified token principal when the token-auth seam attached one.
    principal = getattr(getattr(request.state, "token_principal", None), "principal", None) or "dashboard"

    if action == "cancel":
        existed = clear_drain_request()
        _log.info("Gateway drain CANCEL requested by %s (existed=%s)", principal, existed)
        return {"ok": True, "action": "cancel", "was_draining": existed}
    if action != "drain":
        raise HTTPException(status_code=400, detail=f"Unknown drain action {action!r}; expected 'drain' or 'cancel'")

    payload = write_drain_request(
        principal=str(principal), suppress_notification=bool(body.get("suppress_notification", False)),
    )
    _log.info(
        "Gateway drain BEGIN requested by %s (suppress_notification=%s)", principal, payload["suppress_notification"],
    )
    return {
        "ok": True, "action": "drain", "requested_at": payload["requested_at"],
        # Echo so a caller polling /api/status knows the marker is now set;
        # the gateway watcher flips gateway_state -> draining within ~1s.
        "draining": drain_requested(), "suppress_notification": payload["suppress_notification"],
    }

async def update_hermes():
    """Kick off ``hermes update`` in the background."""
    if is_commit_build(_server_path("PROJECT_ROOT")):
        return _update_refused("commit-build", COMMIT_BUILD_UPDATE_MESSAGE, "")

    if _dashboard_local_update_managed_externally():
        message = _MANAGED_EXTERNALLY_MESSAGE + " The built-in local updater is disabled here."
        # No runnable command exists here: the outer launcher/image owns updates.
        return _update_refused("dashboard_update_managed_externally", message, "")

    # Shared admission gate: marker-first, then the docker/nix/apt heuristics —
    # one decision with the CLI paths.
    from hermes_cli.update_contract import evaluate_update_admission, record_refusal_receipt

    refusal = evaluate_update_admission(_server_path("PROJECT_ROOT"))
    if refusal is not None:
        response = _update_refused(
            _UPDATE_REFUSAL_ERROR_CODES.get(refusal.code, "update_not_in_place"), refusal.message, refusal.update_command,
        )
        record_refusal_receipt(refusal)
        return response

    existing = _ACTION_PROCS.get("hermes-update")
    if existing is not None and existing.poll() is None:
        response = {"ok": True, "pid": existing.pid, "name": "hermes-update", "already_running": True}
        action_id = _ACTION_IDS.get("hermes-update")
        if action_id:
            response["action_id"] = action_id
        return response

    action_id = secrets.token_hex(16)
    with http_failure("Failed to spawn hermes update", 500, "Failed to start update"):
        proc = _spawn_hermes_action(["update"], "hermes-update", env_overrides={"HERMES_ACTION_ID": action_id})
    return {"ok": True, "pid": proc.pid, "name": "hermes-update", "action_id": action_id}

async def get_config_raw(profile: Optional[str] = None):
    """Raw config.yaml text plus its resolved path.

    ``path`` is resolved inside ``_profile_scope`` so the Config page header
    shows the file the switched profile actually reads/writes — /api/status's
    ``config_path`` is machine-global and always reports the dashboard
    process's own profile, which is wrong under the global profile switcher.
    """
    def _run():
        with _profile_scope(profile):
            path = get_config_path()
        if not path.exists():
            return {"yaml": "", "path": str(path)}
        return {"yaml": path.read_text(encoding="utf-8-sig"), "path": str(path)}

    return await asyncio.to_thread(_run)

async def update_config_raw(body: RawConfigUpdate, profile: Optional[str] = None):
    def _run():
        parsed = yaml.safe_load(body.yaml_text)
        if not isinstance(parsed, dict):
            raise HTTPException(status_code=400, detail="YAML must be a mapping")
        with _profile_scope(body.profile or profile):
            # Full-document replacement: the editor owns the whole file; never
            # merge omitted sections back from disk.
            # See #62723.
            approvals_mode_changed = _approval_mode_of(parsed) != _approval_mode_of(read_raw_config())
            save_config(parsed, merge_existing=False)
        # Same indicator refresh as the schema-driven save.
        if approvals_mode_changed and not _is_other_profile(body.profile or profile):
            _broadcast_gateway_session_info()
        return {"ok": True}

    try:
        return await asyncio.to_thread(_run)
    except yaml.YAMLError as e:
        raise HTTPException(status_code=400, detail=f"Invalid YAML: {e}")

async def transcribe_audio_upload(
    payload: AudioTranscriptionRequest, profile: Optional[str] = None
):
    data_url = (payload.data_url or "").strip()
    if not data_url.startswith("data:") or "," not in data_url:
        raise HTTPException(status_code=400, detail="Invalid audio payload")

    header, encoded = data_url.split(",", 1)
    if ";base64" not in header:
        raise HTTPException(status_code=400, detail="Audio payload must be base64 encoded")

    mime_type = (payload.mime_type or header[5:].split(";", 1)[0] or "audio/webm").strip()
    normalized_mime_type = mime_type.split(";", 1)[0].lower()
    if not (normalized_mime_type.startswith("audio/") or normalized_mime_type == "video/webm"):
        raise HTTPException(status_code=400, detail="Payload must be an audio recording")

    try:
        audio_bytes = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError):
        raise HTTPException(status_code=400, detail="Audio payload is not valid base64")

    if not audio_bytes:
        raise HTTPException(status_code=400, detail="Audio recording is empty")
    if len(audio_bytes) > _MAX_TRANSCRIPTION_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="Audio recording is too large")

    temp_path = ""
    try:
        with http_failure("Desktop voice transcription failed", 500, "Transcription failed"):
            with tempfile.NamedTemporaryFile(
                prefix="hermes-desktop-voice-", suffix=_audio_extension_for_mime(mime_type),
                delete=False,
            ) as tmp:
                tmp.write(audio_bytes)
                temp_path = tmp.name

            # transcribe_recording (not raw transcribe_audio): filters Whisper
            # hallucinations and maps provider "empty transcript" errors to a
            # successful empty result — the live voice loop treats "" as silence
            # and re-listens instead of surfacing a 400 on every quiet turn.
            from tools.voice_mode import transcribe_recording

            result = await _run_config_scoped(profile, lambda: transcribe_recording(temp_path))
    finally:
        if temp_path:
            _unlink_quietly(temp_path)

    if not result.get("success"):
        err = result.get("error") or "Transcription failed"
        # No speech detected is a normal outcome for VAD/continuous voice loops
        # (re-listening on silence), not an error: return an empty transcript so
        # the client quietly re-listens instead of showing a failure toast.
        if "empty transcript" in err.lower():
            return {"ok": True, "transcript": "", "provider": result.get("provider")}
        raise HTTPException(status_code=400, detail=err)

    return {
        "ok": True, "transcript": str(result.get("transcript") or "").strip(),
        "provider": result.get("provider"),
    }

async def get_elevenlabs_voices(profile: Optional[str] = None):
    """Return ElevenLabs voices when an API key is configured.

    The desktop UI uses this for the ``tts.elevenlabs.voice_id`` dropdown.
    Only non-secret voice metadata is returned; the API key stays server-side.
    """
    # Config-only scope (await-safe): the key lookup reads the requested
    # profile's .env, matching the profile the settings UI writes to.
    with _config_profile_scope(profile):
        api_key = (load_env().get("ELEVENLABS_API_KEY") or "").strip()
    if not api_key:
        # Fallback for env-only deployments — scope-aware: under multiplex
        # os.environ may hold another profile's key, so honor the installed
        # scope's verdict. Only the unscoped default-profile path
        # (UnscopedSecretError) reads the env; any other failure stays empty.
        try:
            from agent.secret_scope import UnscopedSecretError, get_secret

            try:
                api_key = (get_secret("ELEVENLABS_API_KEY") or "").strip()
            except UnscopedSecretError:
                api_key = (os.environ.get("ELEVENLABS_API_KEY") or "").strip()
        except Exception:
            pass
    if not api_key:
        return {"available": False, "voices": []}

    request = urllib.request.Request(
        "https://api.elevenlabs.io/v1/voices",
        headers={"Accept": "application/json", "xi-api-key": api_key},
    )

    try:
        def _fetch() -> dict[str, Any]:
            with urllib.request.urlopen(request, timeout=10) as response:
                return _read_dashboard_json_response(response)

        payload = await asyncio.to_thread(_fetch)
    except urllib.error.HTTPError as exc:
        # An auth failure (bad/expired/scoped key) is a persistent, user-fixable
        # state and the desktop polls this on every settings open/focus, so
        # treat 401/403 as "integration unavailable": 200 to the UI and log at
        # most once until the error signature changes.
        if exc.code in (401, 403):
            if _voice_list_error_logged_once(f"http-{exc.code}"):
                _log.info("ElevenLabs voices unavailable: %s — check ELEVENLABS_API_KEY", exc)
            return {"available": False, "voices": [], "error": "unauthorized"}
        if _voice_list_error_logged_once(f"http-{exc.code}"):
            _log.warning("ElevenLabs voice list failed: %s", exc)
        raise HTTPException(status_code=502, detail="Could not load ElevenLabs voices")
    except Exception as exc:
        if _voice_list_error_logged_once(str(exc)):
            _log.warning("ElevenLabs voice list failed: %s", exc)
        raise HTTPException(status_code=502, detail="Could not load ElevenLabs voices")
    _voice_list_error_logged_once(None)  # success — re-arm logging for next failure

    voices = []
    for voice in payload.get("voices") or []:
        if not isinstance(voice, dict):
            continue

        voice_id = str(voice.get("voice_id") or "").strip()
        if not voice_id:
            continue

        voices.append({
            "voice_id": voice_id, "name": str(voice.get("name") or voice_id),
            "label": _elevenlabs_voice_label(voice),
        })

    voices.sort(key=lambda item: str(item.get("label") or "").lower())
    return {"available": True, "voices": voices}

async def tts_lease(payload: TTSLeaseRequest, profile: Optional[str] = None):
    """Desktop TTS-output toggles as warm-up / release signals.

    ``active: true`` registers a lease on the TTS engine and pre-loads the
    configured provider (local model, lazily-installed SDK) so the first spoken
    reply doesn't pay the load as dead air; ``active: false`` drops the lease
    and, once no surface holds one, unloads resident local models. Blocking
    work runs off the event loop. Warm-up failures are reported in the body,
    never as an HTTP error — the toggle must succeed even when preload fails.
    """
    lease = (payload.lease or "").strip()
    if not lease:
        raise HTTPException(status_code=400, detail="lease is required")

    def _apply():
        from tools.tts_tool_lifecycle import acquire_tts_lease, release_tts_lease
        if payload.active:
            with _config_profile_scope(profile):
                return acquire_tts_lease(lease)
        # Release reads the requester's keep_warm_seconds, but must drop the lease even when
        # that profile is gone — a stuck lease pins the local model in memory.
        try:
            with _config_profile_scope(profile):
                return release_tts_lease(lease)
        except HTTPException:
            return release_tts_lease(lease)

    try:
        result = await asyncio.to_thread(_apply)
    except HTTPException:
        raise
    except Exception as exc:
        _log.warning("TTS lease %s (%s) failed: %s", lease, payload.active, exc)
        result = {"leases": None, "action": "error", "error": str(exc)}
    return {"ok": True, "lease": lease, "active": payload.active, **result}

async def stt_lease(payload: STTLeaseRequest, profile: Optional[str] = None):
    """Desktop voice-input sessions as STT warm-up / release signals.

    ``active: true`` registers a lease and pre-loads the configured local STT
    model (first-use download + load) so the transcription request doesn't pay
    the cold cost inside its timeout; ``active: false`` drops the lease. The
    model stays resident after the last release — it is shared with the
    gateway/CLI surfaces in this process, and ``stt.local.unload_after_idle_seconds``
    still governs eviction. Blocking work runs off the event loop. Warm-up
    failures are reported in the body, never as an HTTP error — recording must
    start even when preload fails.
    """
    lease = (payload.lease or "").strip()
    if not lease:
        raise HTTPException(status_code=400, detail="lease is required")

    def _apply():
        from tools.stt_lease import acquire_stt_lease, release_stt_lease
        if payload.active:
            with _config_profile_scope(profile):
                return acquire_stt_lease(lease)
        return release_stt_lease(lease)

    try:
        result = await asyncio.to_thread(_apply)
    except HTTPException:
        raise
    except Exception as exc:
        _log.warning("STT lease %s (%s) failed: %s", lease, payload.active, exc)
        result = {"leases": None, "action": "error", "error": str(exc)}
    return {"ok": True, "lease": lease, "active": payload.active, **result}

async def console_ws(ws: WebSocket) -> None:
    gate = await _ws_gate(ws, "console")
    if gate is None:
        return
    peer, mode, cred = gate
    await ws.accept()

    profile = (ws.query_params.get("profile") or "").strip() or None
    out = _ConsoleSender(ws)

    try:
        from hermes_cli.console_engine import HermesConsoleEngine

        engine = HermesConsoleEngine(output_limit=_CONSOLE_OUTPUT_LIMIT)
        if profile and profile.lower() != "current":
            _resolve_profile_dir(profile)
    except HTTPException as exc:
        await out.error(str(exc.detail), prompt="")
        await ws.close(code=4400, reason=_ws_close_reason(str(exc.detail)))
        return
    except Exception as exc:
        _log.exception("console failed to initialize")
        await out.error(f"Console unavailable: {exc}", prompt="")
        await ws.close(code=1011)
        return

    _log.info("console accepted peer=%s mode=%s cred=%s profile=%s", peer, mode, cred, profile or "current")
    await out.prompt(type="ready", profile=profile or "current")

    active_task: asyncio.Task | None = None
    pending_confirmation: Optional[str] = None
    command_generation = 0

    async def run_command(line: str, *, confirmed: bool, command_id: int) -> None:
        nonlocal active_task, pending_confirmation, command_generation
        scope = InterruptScope()
        worker = _get_console_executor().submit(
            _execute_console_line, engine, line, confirmed=confirmed, profile=profile, scope=scope,
        )
        try:
            result = await _wait_for_console_worker(worker)
        except asyncio.CancelledError:
            await _unwind_console_worker(worker, scope, "cancelled")
            raise
        except TimeoutError:
            await _unwind_console_worker(worker, scope, "timed out")
            if command_id == command_generation:
                pending_confirmation = None
                await out.error_then_complete(
                    "Command timed out. Hermes Console returned to the prompt.", line, command_id, "timeout",
                )
        except Exception as exc:
            if command_id == command_generation:
                pending_confirmation = None
                _log.exception("console command failed")
                await out.error_then_complete(str(exc) or exc.__class__.__name__, line, command_id, "error")
        else:
            if command_id != command_generation:
                return
            pending_confirmation = result.command if result.status == "confirm_required" else None
            await out.send_result(result, command_id=command_id)
            if result.status == "exit":
                await ws.close(code=1000)
        finally:
            if command_id == command_generation:
                active_task = None

    def start_command(line: str, *, confirmed: bool = False) -> None:
        nonlocal active_task, command_generation
        command_generation += 1
        active_task = asyncio.create_task(run_command(line, confirmed=confirmed, command_id=command_generation))

    try:
        while True:
            try:
                msg = await ws.receive()
            except RuntimeError:
                break
            if msg.get("type") == "websocket.disconnect":
                break

            payload, error = _console_json_payload(msg)
            if error:
                await out.prompt(type="error", message=error)
                continue
            if payload is None:
                continue

            frame_type = str(payload.get("type") or "").strip().lower()
            if frame_type == "ping":
                await out.prompt(type="pong")
                continue

            if frame_type == "cancel":
                if active_task and not active_task.done():
                    command_generation += 1
                    task, active_task = active_task, None
                    task.cancel()
                    # Report cancelled only once the worker (and any provider request it owns) is gone.
                    with contextlib.suppress(asyncio.CancelledError):
                        await task
                    pending_confirmation = None
                    await out.prompt(type="complete", status="cancelled")
                elif pending_confirmation:
                    pending_confirmation = None
                    await out.prompt(type="complete", status="cancelled")
                else:
                    await out.prompt(type="complete", status="idle")
                continue

            if active_task and not active_task.done():
                await out.prompt(type="error", message="A console command is already running.")
                continue

            if frame_type == "confirm":
                command = str(payload.get("command") or pending_confirmation or "").strip()
                if not pending_confirmation:
                    await out.prompt(type="error", message="No command is waiting for confirmation.")
                    continue
                if command != pending_confirmation:
                    await out.prompt(type="error", message="Confirmation does not match the pending command.")
                    continue
                pending_confirmation = None
                start_command(command, confirmed=True)
                continue

            if frame_type in {"input", "command"}:
                line = str(payload.get("line") or payload.get("command") or "").strip()
                if not line:
                    await out.prompt(type="complete", status="ok")
                    continue
                if pending_confirmation:
                    await out.prompt(
                        type="error",
                        message="Confirm or cancel the pending command before running another one.",
                    )
                    continue
                start_command(line)
                continue

            await out.prompt(type="error", message=f"Unsupported console frame: {frame_type or '?'}")
    except WebSocketDisconnect:
        pass
    finally:
        if active_task and not active_task.done():
            active_task.cancel()
            try:
                await active_task
            except (asyncio.CancelledError, Exception):
                pass

async def pub_ws(ws: WebSocket) -> None:
    channel = await _accept_channel_ws(ws)
    if channel is None:
        return
    try:
        while True:
            await _broadcast_event(ws.app, channel, await ws.receive_text())
    except WebSocketDisconnect:
        pass

async def events_ws(ws: WebSocket) -> None:
    channel = await _accept_channel_ws(ws)
    if channel is None:
        return
    event_channels, event_lock = _get_event_state(ws.app)
    async with event_lock:
        event_channels.setdefault(channel, set()).add(ws)
    try:
        while True:
            # Subscribers don't speak — receive() just blocks until disconnect.
            await ws.receive_text()
    except WebSocketDisconnect:
        pass
    finally:
        async with event_lock:
            subs = event_channels.get(channel)
            if subs is not None:
                subs.discard(ws)
                if not subs:
                    event_channels.pop(channel, None)

async def validate_custom_endpoint(body: CustomEndpointUpdate):
    """Probe a custom endpoint by calling its OpenAI-compatible /models URL."""
    base_url = (body.base_url or "").strip().rstrip("/")
    if not base_url:
        return {"ok": False, "reachable": True, "message": "Enter an endpoint URL first.", "models": []}

    headers = {"Accept": "application/json"}
    if body.api_key and body.api_key.strip():
        headers["Authorization"] = f"Bearer {body.api_key.strip()}"

    resolved, resp = await _probe_openai_compatible_models(base_url, headers)
    if resp is None:
        return {"ok": False, "reachable": False, "message": f"Could not reach {base_url}/models.", "models": []}
    if resp.status_code in (401, 403):
        return {"ok": False, "reachable": True, "message": "The endpoint rejected the API key.", "models": []}
    if not resp.is_success:
        return {"ok": False, "reachable": True, "message": f"Endpoint returned HTTP {resp.status_code}.", "models": []}
    # ``models`` stays the bare id list older clients read; ``model_details`` keeps the
    # alias metadata (``canonical_model`` / ``reasoning_effort``) the id list flattens.
    entries = _parse_model_entries(resp)
    ids = [e["id"] for e in entries]
    if not ids:
        # A 200 that parses to zero models is the SPA-catch-all signature (#83128): a real
        # OpenAI-compatible /models answers JSON with a usable list. ``_parse_model_entries``
        # is lenient by design, so classify the empty result here instead of reporting
        # success. ok:false + reachable:true is a warning in the UI — Save stays possible
        # for endpoints that legitimately expose no model list.
        return {"ok": False, "reachable": True, "message": _no_models_probe_message(resp, resolved),
                "models": [], "model_details": [], "resolved_base_url": resolved}
    # /models answering proves nothing about the transport the runtime will POST to:
    # a Responses-only host lists models fine and 404s every /chat/completions (#93622).
    # Probe the route the saved mode (or the runtime's URL auto-detect) actually uses, on the
    # base that actually served /models (#65488) — that is the URL the runtime will persist.
    mode = _canonical_api_mode(body.api_mode or "").lower() or _auto_api_mode(resolved)
    probe_model = (body.model or "").strip() or (ids[0] if ids else "")
    try:
        async with _endpoint_probe_client(resolved, 8.0) as client:
            missing = await _probe_transport_route(client, resolved, mode, probe_model, headers)
    except Exception:
        missing = ""  # inconclusive (see _probe_transport_route): never block on a transport error

    result = {"ok": True, "reachable": True, "message": "", "models": ids, "model_details": entries,
              "transport_checked": mode, "resolved_base_url": resolved}
    if missing:
        result.update(ok=False, message=missing)
    return result

async def validate_provider_credential(body: EnvVarUpdate, request: Request):
    """Live-probe a provider credential before it's saved.

    Returns {ok, reachable, message}. ok=True means the provider accepted the
    key; ok=False + reachable=True means the key is bad (caller should block);
    reachable=False means the network probe couldn't run (caller may save with
    a warning rather than hard-blocking offline users).
    """
    _require_token(request)
    import httpx

    key = (body.key or "").strip()
    value = (body.value or "").strip()
    if not value:
        return {"ok": False, "reachable": True, "message": "Enter a value first."}

    # Local / custom endpoint: validate connectivity, not auth — any HTTP
    # response (even 401) proves the endpoint is up. Also surface the model ids
    # it advertises (OpenAI ``/v1/models`` shape) so the GUI can auto-pick a
    # default. The optional API key is sent so servers that require auth on
    # ``/v1/models`` still enumerate instead of returning an empty list.
    if key == "OPENAI_BASE_URL":
        api_key = (body.api_key or "").strip()
        headers = {"Authorization": f"Bearer {api_key}"} if api_key else None
        resolved, resp = await _probe_openai_compatible_models(value, headers)
        url = resolved + "/models"
        if resp is None:
            return {"ok": False, "reachable": False, "message": f"Could not reach {url}."}
        entries = _parse_model_entries(resp)
        models = [e["id"] for e in entries]
        if not models and not resp.is_success:
            # A proxy/gateway error page parses as "no models"; name the status instead so the
            # GUI does not tell the user to "start a model" on a server that answered.
            return {"ok": False, "reachable": True, "message": f"{url} answered HTTP {resp.status_code}.", "models": []}
        return {"ok": True, "reachable": True, "message": "", "models": models, "model_details": entries,
                "resolved_base_url": resolved}

    probe = _CREDENTIAL_PROBES.get(key)
    if not probe:
        # No probe for this provider — can't validate, don't block.
        return {"ok": True, "reachable": False, "message": ""}

    url, auth = probe
    if key == "GEMINI_API_KEY":
        from agent.gemini_native_adapter import normalize_gemini_base_url
        # Normalize guarantees the version segment; the key itself never decides the surface —
        # AQ. keys exist for both AI Studio and Vertex express mode (#115306).
        url = normalize_gemini_base_url(url.rsplit("/models", 1)[0]) + "/models"
    headers = {"Accept": "application/json"}
    params = {}
    if auth == "bearer":
        headers["Authorization"] = f"Bearer {value}"
    else:
        params["key"] = value

    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(10.0)) as client:
            resp = await client.get(url, headers=headers, params=params)
    except Exception:
        return {"ok": False, "reachable": False, "message": "Could not reach the provider to verify the key."}

    if resp.status_code in (401, 403):
        return {"ok": False, "reachable": True, "message": "That API key was rejected. Double-check it and try again."}
    if resp.status_code == 429 or resp.is_success:
        # 429 = key is valid but rate-limited; success = valid.
        return {"ok": True, "reachable": True, "message": ""}
    return {"ok": False, "reachable": True, "message": f"Provider returned HTTP {resp.status_code} for this key."}

