async def update_messaging_platform(platform_id: str, body: MessagingPlatformUpdate, profile: Optional[str] = None):
    target_profile = body.profile or profile

    def _resolve():
        # Plugin platforms (and their value rules) are registered per profile: resolve them in the
        # target's scope, the catalog GET /api/messaging/platforms?profile= lists.
        with _profile_scope(target_profile):
            return _require_platform(platform_id), _env_value_rules(platform_id)

    entry, env_value_rules = await asyncio.to_thread(_resolve)
    if body.enabled:
        conflict = await asyncio.to_thread(_multiplex_port_binding_conflict, platform_id, target_profile)
        if conflict:
            # Reject BEFORE any .env/config.yaml write so the profile stays
            # loadable by the multiplexed gateway.
            _log.info(
                "Rejected messaging platform update: platform=%s profile=%s "
                "(multiplex port-binding conflict)", platform_id, target_profile or "current",
            )
            raise HTTPException(status_code=409, detail=conflict)

    allowed_env = set(entry["env_vars"])

    def _check_allowed(key: str) -> None:
        if key not in allowed_env:
            raise HTTPException(status_code=400, detail=f"{key} is not configurable for {entry['name']}")

    def _apply():
        with _profile_scope(target_profile):
            updates: dict[str, str] = {}

            # Validate the whole request before clearing or replacing anything.
            for key in body.clear_env:
                _check_allowed(key)
            for key, value in body.env.items():
                _check_allowed(key)
                trimmed = value.strip()
                if not trimmed:
                    continue
                if is_redacted_credential_preview(trimmed):
                    raise HTTPException(status_code=400, detail=REDACTED_CREDENTIAL_WRITE_DETAIL)
                _validate_messaging_env_value(env_value_rules, key, trimmed)
                updates[key] = trimmed

            for key in body.clear_env:
                remove_env_value(key)
            for key, value in updates.items():
                save_env_value(key, value)

            if body.enabled is not None:
                _write_platform_enabled(platform_id, body.enabled)

    with http_failure(f"PUT /api/messaging/platforms/{platform_id} failed", 500, detail="Internal server error"):
        await asyncio.to_thread(_apply)

        # Audit trail for channel config mutations: names only, never values.
        _log.info(
            "Messaging platform updated: platform=%s profile=%s enabled=%s "
            "env_keys=%s cleared_keys=%s",
            platform_id, target_profile or "current", body.enabled, sorted(body.env), sorted(body.clear_env),
        )
        # A live multiplexer serving this named profile builds the adapter from the new token now
        # (its periodic rescan would otherwise pick it up within a cycle); no gateway restart.
        hot_served = await asyncio.to_thread(_notify_multiplexer_hot_serve, target_profile)
        return {"ok": True, "platform": platform_id, "hot_served": hot_served}

async def test_messaging_platform(platform_id: str, profile: Optional[str] = None):
    def _run():
        with _profile_scope(profile) as scoped_dir:
            entry = _require_platform(platform_id)
            authz_env = _platform_authz_env_names(platform_id)
            payload = _platform_payloads(scoped_dir, [entry])[0]
            posture = None
            if payload["state"] == "connected":
                # Still inside the profile scope: load_env()/load_config()/PairingStore
                # must resolve the ACTIVE profile's env/config/pairing store, not the
                # dashboard process's root home.
                posture = _messaging_platform_posture(platform_id, entry, scoped_dir is not None, authz_env)
            return entry, payload, posture

    entry, payload, posture = await asyncio.to_thread(_run)

    def result(ok: bool, message: str) -> dict[str, Any]:
        return {"ok": ok, "state": payload["state"], "message": message}

    if not payload["enabled"]:
        return result(False, f"{entry['name']} is disabled. Enable it, then restart the gateway.")
    if not payload["configured"]:
        missing = [field["key"] for field in payload["env_vars"] if field["required"] and not field["is_set"]]
        return result(False, f"Missing required setup: {', '.join(missing)}" if missing else "Platform setup is incomplete.")
    if not payload["gateway_running"]:
        return result(False, "Gateway is not running. Restart the gateway to connect this platform.")
    if payload["state"] == "connected":
        # Non-breaking extension (#66030): keep ok=True (the connection is genuinely up)
        # but surface the platform's auth posture so the UI can render yellow on
        # connected-but-unreachable, and say exactly what to configure.
        if posture is None:
            return result(True, f"{entry['name']} is connected.")
        return {
            "ok": True,
            "state": payload["state"],
            "message": posture["message"],
            "auth_posture": posture["posture"],
        }
    if payload.get("error_message"):
        return result(False, payload["error_message"])
    return result(False, "Setup looks complete, but the gateway has not reported a connection yet. Restart the gateway.")

def get_model_info(profile: Optional[str] = None):
    """Resolved metadata for the configured model: auto-detected vs configured
    context length (so the UI can show "Auto-detected: 200K" beside the
    override) plus models.dev capabilities when available."""
    try:
        model_cfg = _load_config_scoped(profile).get("model", "")
        model_name, provider = _main_model_fields(model_cfg)
        base_url = model_cfg.get("base_url", "") if isinstance(model_cfg, dict) else ""
        config_ctx = model_cfg.get("context_length") if isinstance(model_cfg, dict) else None

        if not model_name:
            return dict(_EMPTY_MODEL_INFO, provider=provider)

        try:
            # config_context_length=None: ignore the override — we want the auto value.
            # Bounded: the resolver's provider probes can hang for tens of seconds
            # when model.base_url is unreachable (#63214).
            auto_ctx = _bounded_context_length_probe(model_name, base_url, provider)
        except Exception:
            auto_ctx = 0

        config_ctx_int = config_ctx if isinstance(config_ctx, int) and config_ctx > 0 else 0

        caps = {}
        try:
            from agent.models_dev import get_model_capabilities
            mc = get_model_capabilities(provider=provider, model=model_name)
            if mc is not None:
                caps = {name: getattr(mc, name) for name in _CAPABILITY_FIELDS}
        except Exception:
            pass

        return {
            "model": model_name, "provider": provider, "auto_context_length": auto_ctx,
            "config_context_length": config_ctx_int,
            "effective_context_length": config_ctx_int or auto_ctx,  # what the agent actually uses
            "capabilities": caps,
        }
    except HTTPException:
        # Unknown/invalid profile must surface as 404, not degrade into a
        # 200 with empty model info (which would render as "no model set").
        raise
    except Exception:
        _log.exception("GET /api/model/info failed")
        return dict(_EMPTY_MODEL_INFO)

def get_recommended_default_model(provider: str = "", profile: Optional[str] = None):
    """Recommended default model for a freshly-authenticated provider, mirroring
    ``hermes model``'s curation so GUI onboarding lands on a sensible default.
    Nous honors the user's free/paid tier. Any other provider gets the preferred
    silent default when its curated list carries it, else the first curated model —
    aggregator lists lead with the priciest Anthropic flagship, which must never be
    the model a user lands on without explicitly picking it.
    Response: {"provider", "model", "free_tier": bool | None} — free_tier only for
    Nous; ``model`` may be empty (caller degrades gracefully)."""
    slug = (provider or "").strip().lower()

    if slug == "nous":
        try:
            # The tier, Portal URL and recommendation caches are all per profile home.
            with _config_profile_scope(profile):
                return _nous_recommended_default()
        except HTTPException:
            raise  # an unknown ?profile= is the scope's 404, not an empty recommendation
        except Exception:
            _log.exception("GET /api/model/recommended-default (nous) failed")
            return {"provider": "nous", "model": "", "free_tier": None}

    try:
        from hermes_cli.inventory import build_models_payload, load_picker_context
        from hermes_cli.models import pick_silent_default_model

        # build_models_payload -> list_authenticated_providers -> _save_discovered_models_to_config:
        # this GET lazily PERSISTS discovered custom-provider models, so it needs the scope too.
        with _config_profile_scope(profile):
            payload = build_models_payload(load_picker_context())
        for row in payload.get("providers", []):
            if str(row.get("slug", "")).lower() == slug:
                models = [str(m) for m in (row.get("models") or [])]
                return {"provider": slug, "model": pick_silent_default_model(models, provider=slug), "free_tier": None}
        return {"provider": slug, "model": "", "free_tier": None}
    except HTTPException:
        raise  # an unknown ?profile= is the scope's 404, not an empty recommendation
    except Exception:
        _log.exception("GET /api/model/recommended-default failed")
        return {"provider": slug, "model": "", "free_tier": None}

async def list_oauth_providers(profile: Optional[str] = None):
    """Every OAuth-capable provider with current status (token_preview is the last
    N chars, never the full token; disconnect_command only for external providers)."""
    def _run():
        providers = []
        for p in _build_oauth_catalog():
            status = _resolve_provider_status(p["id"], p.get("status_fn"))
            disconnect_hint = _oauth_provider_disconnect_hint(p, status)
            providers.append({
                "id": p["id"], "name": p["name"], "flow": p["flow"],
                "cli_command": _external_process_cli_command(p["id"], p["cli_command"]),
                "docs_url": p["docs_url"], "disconnect_hint": disconnect_hint,
                "disconnect_command": _oauth_provider_disconnect_command(p),
                "disconnectable": disconnect_hint is None, "status": status,
            })
        return {"providers": providers}

    return await scoped_to_thread(profile, _run)

async def disconnect_oauth_provider(provider_id: str, request: Request, profile: Optional[str] = None):
    """Disconnect an OAuth provider. Token-protected (matches /env/reveal)."""
    _require_token(request)

    def _run():
        catalog_by_id = {p["id"]: p for p in _build_oauth_catalog()}
        provider = catalog_by_id.get(provider_id)
        if provider is None:
            raise HTTPException(400, f"Unknown provider: {provider_id}. Available: {', '.join(sorted(catalog_by_id))}")
        # Flow-only rejection first so external providers never reach status resolution.
        _reject_if_not_disconnectable(provider, {})
        _reject_if_not_disconnectable(provider, _resolve_provider_status(provider_id, provider.get("status_fn")))

        if provider_id == "anthropic":
            try:
                cleared = _clear_anthropic_auth()
            except HTTPException:
                raise
            except Exception:
                _log.exception("disconnect %s failed", provider_id)
                raise _disconnect_http_error(500, provider["name"])
            if not cleared:
                raise _disconnect_http_error(409, provider["name"])
            _log.info("oauth/disconnect: %s", provider_id)
            return {"ok": True, "provider": provider_id}
        try:
            from hermes_cli.auth import clear_provider_auth, invalidate_nous_auth_status_cache
            cleared = clear_provider_auth(provider_id)
            if provider_id == "nous":
                invalidate_nous_auth_status_cache()
            if not cleared:
                raise _disconnect_http_error(409, provider["name"])
            _log.info("oauth/disconnect: %s (cleared=%s)", provider_id, cleared)
            return {"ok": True, "provider": provider_id}
        except HTTPException:
            raise
        except Exception:
            _log.exception("disconnect %s failed", provider_id)
            raise _disconnect_http_error(500, provider["name"])

    return await scoped_to_thread(profile, _run)

async def approve_pairing(body: PairingApprove):
    store = _pairing_store(body.profile)
    platform = (body.platform or "").lower().strip()
    # `request_id` is what an admin surface sends after listing pending requests;
    # `code` is the one-time code the user relays. A request-id-shaped value in
    # the older `code` field still routes to the request path.
    target = (body.request_id or body.code or "").strip()
    if not platform or not target:
        raise HTTPException(status_code=400, detail="platform and request_id or code are required")

    by_request_id = bool(body.request_id) or store.looks_like_request_id(target)
    if by_request_id:
        result = await asyncio.to_thread(store.approve_request, platform, target)
    else:
        result = await asyncio.to_thread(store.approve_code, platform, target.upper())
    if result:
        return {"ok": True, "user": result}
    # Lockout only gates the code path — a stale request id must not surface
    # as a bogus 429 while the platform is locked out for an unrelated reason.
    if not by_request_id and store._is_locked_out(platform):
        raise HTTPException(
            status_code=429, detail=f"Platform '{platform}' is locked out after too many failed approvals.",
        )
    raise HTTPException(
        status_code=404, detail=f"Pairing request or code not found or expired for platform '{platform}'.",
    )

async def revoke_pairing(body: PairingRevoke):
    store = _pairing_store(body.profile)
    platform = (body.platform or "").lower().strip()
    if not platform or not body.user_id:
        raise HTTPException(status_code=400, detail="platform and user_id are required")
    if await asyncio.to_thread(store.revoke, platform, body.user_id):
        return {"ok": True}
    raise HTTPException(status_code=404, detail=f"User {body.user_id} not found in approved list for {platform}.")

